#!/usr/bin/env node
/**
 * Emit tdb-verse-accuracy.js from the same lock tables the build uses.
 * Do not hand-edit the generated file.
 */
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import { PHRASE_LOCKS, SPEAKER_RULES } from './lib/verse-teaching-guard.mjs';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(__dirname, '..');
const outPath = path.join(root, 'tdb-verse-accuracy.js');

function packRe(re, extra) {
  if (!re) return null;
  return { source: re.source, flags: re.flags, extra: extra || null };
}

const locks = PHRASE_LOCKS.map((lock) => ({
  id: lock.id,
  re: lock.re.source,
  flags: lock.re.flags,
  allow: lock.allow ? lock.allow.source : null,
  allowFlags: lock.allow ? lock.allow.flags : ''
}));

const speakers = SPEAKER_RULES.map((rule) => ({
  id: rule.id,
  name: packRe(rule.name),
  allow: packRe(rule.allow),
  unless: packRe(rule.unless),
  psalmCh: rule.psalmCh || null
}));

const body = `/**
 * Runtime verse-accuracy lock. Generated by scripts/build-verse-accuracy-runtime.mjs.
 * Do not edit by hand — locks live in scripts/lib/verse-teaching-guard.mjs.
 */
(function (global) {
  'use strict';
  var LOCKS = ${JSON.stringify(locks, null, 2)};
  var SPEAKERS = ${JSON.stringify(speakers, null, 2)};

  function normalizeRef(ref) {
    return String(ref || '')
      .replace(/\\s*\\(KJV\\)\\s*$/i, '')
      .replace(/^Psalms\\s+/i, 'Psalm ')
      .replace(/\\s+/g, ' ')
      .trim();
  }

  function bookOf(ref) {
    var m = String(ref || '').match(/^((?:[1-3]\\s+)?[A-Za-z][A-Za-z\\s.]+?)\\s+\\d+:/);
    return m ? m[1].replace(/\\./g, '').replace(/\\s+/g, ' ').trim() : '';
  }

  function chapterOf(ref) {
    var m = String(ref || '').match(/\\s+(\\d+):\\d+/);
    return m ? Number(m[1]) : 0;
  }

  function leadingSpeakerInText(text) {
    var t = String(text || '').replace(/^What was going on:\\s*/i, '').replace(/^What it means:\\s*/i, '').trim();
    var m = t.match(/^(?:the\\s+apostle\\s+|the\\s+prophet\\s+)?(solomon|paul|david|peter|james|jude|isaiah|moses|john)\\b/i);
    return m ? m[1] : '';
  }

  function situationLooksWrongForRef(sit, ref) {
    var s = String(sit || '');
    var r = normalizeRef(ref);
    if (!s || !r) return false;
    for (var i = 0; i < LOCKS.length; i++) {
      var lock = LOCKS[i];
      if (!new RegExp(lock.re, lock.flags).test(s)) continue;
      if (!lock.allow) return true;
      if (!new RegExp(lock.allow, lock.allowFlags).test(r)) return true;
    }
    var lead = leadingSpeakerInText(s);
    if (lead && !speakerBelongsToBook(lead, r)) return true;
    return false;
  }

  function speakerBelongsToBook(about, ref) {
    var a = String(about || '').toLowerCase();
    var book = bookOf(ref).toLowerCase().replace(/^psalms$/, 'psalm');
    if (!a || !book) return true;
    var ch = chapterOf(ref);
    var matched = 0;
    var allowed = 0;
    for (var i = 0; i < SPEAKERS.length; i++) {
      var rule = SPEAKERS[i];
      if (!new RegExp(rule.name.source, rule.name.flags).test(a)) continue;
      if (rule.unless && new RegExp(rule.unless.source, rule.unless.flags).test(a)) continue;
      matched += 1;
      if (new RegExp(rule.allow.source, rule.allow.flags).test(book)) {
        allowed += 1;
        continue;
      }
      if (rule.psalmCh && /^psalm/.test(book) && rule.psalmCh.indexOf(ch) !== -1) allowed += 1;
    }
    if (!matched) return true;
    return allowed > 0;
  }

  function sanitize(ref, fields) {
    var f = fields || {};
    var who = String(f.who || f.about || '');
    var situation = String(f.situation || f.setting || '');
    var audience = String(f.audience || f.to || '');
    var plain = String(f.plain || '');
    var blocked = [];
    if (who && !speakerBelongsToBook(who, ref)) {
      blocked.push('who');
      who = '';
    }
    if (situation && situationLooksWrongForRef(situation, ref)) {
      blocked.push('situation');
      situation = '';
    }
    if (audience && situationLooksWrongForRef(audience, ref)) {
      blocked.push('audience');
      audience = '';
    }
    if (plain && situationLooksWrongForRef(plain, ref)) {
      blocked.push('plain');
      plain = '';
    }
    return { who: who, situation: situation, audience: audience, plain: plain, blocked: blocked };
  }

  global.TDB_verseAccuracy = {
    version: '2026-08-15',
    locks: LOCKS,
    speakers: SPEAKERS,
    normalizeRef: normalizeRef,
    situationLooksWrongForRef: situationLooksWrongForRef,
    speakerBelongsToBook: speakerBelongsToBook,
    sanitize: sanitize
  };
})(typeof window !== 'undefined' ? window : globalThis);
`;

fs.writeFileSync(outPath, body, 'utf8');
console.log(
  'build-verse-accuracy-runtime: wrote',
  path.relative(root, outPath),
  'locks=',
  locks.length,
  'speakers=',
  speakers.length
);
